QP_SOLVER_PREFERENCE <- c(OSQP_SOLVER, GUROBI_SOLVER, XPRESS_SOLVER, CPLEX_SOLVER, HIGHS_SOLVER, PIQP_SOLVER)

## Conic solver preference order (matches CVXPY defines.py CONIC_SOLVERS)
